insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-230', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Développer des capacités à observer, comparer, raisonner (de manière inductive et déductive), conceptualiser, abstraire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-231', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Développer l’apprentissage explicite d’un vocabulaire et de supports langagiers permettant d’exprimer les relations de causalité, de temporalité et de chronologie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-232', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Développer son environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques que l’élève mobilise et agence pour apprendre.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-233', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Acquérir une conscience des apprentissages et notamment apprendre à s’autoévaluer, c’est-à-dire à identifier et à évaluer ses savoirs, ses savoir-faire et compétences, ainsi que ceux à développer et à améliorer.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-234', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Acquérir une conscience des apprentissages et notamment être capable d’analyser soi-même ses propres démarches et procédures d’apprentissage (métacognition) pour enclencher une autorégulation dans son travail, ce qui suppose, au besoin, un changement de stratégie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-235', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Développer une pensée critique et complexe', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-236', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Trouver, traiter et évaluer des sources d’informations, quel qu’en soit le support, y compris numérique, ce qui suppose notamment la capacité à évaluer la fiabilité des informations, en se posant les questions relatives au(x) producteur(s) et au contexte de production de l’information, pour identifier l’intention du producteur, son rapport aux informations traitées, les procédés utilisés pour produire un effet sur soi et sur autrui.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
