insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-241', (select id from public.curriculum_item where version = '2022' and code = 'FR-0'), 'primaire', array['S3']::text[], 'Français', 'competence', 'Découvrir différents milieux professionnels et leur diversité et être sensibilisé tant aux contributions sociétales qu’aux enjeux éthiques liés à ces divers mondes socioprofessionnels.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
