insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P3-94-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-94'), 'primaire', array['P3']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - les connaissances personnelles mobilisées/modifiées ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (texte-illustrations) ; - les mots appartenant à un même champ lexical.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
