insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-77-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-77'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Restituer un contenu/message donné', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-78-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-78'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Prendre la parole pour restituer un contenu/message donné avec expression :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-79-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-79'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- en tenant compte de l’intention et du destinataire ; - en adaptant le volume, le débit, la posture, les expressions et le regard ; - en utilisant les étapes d’une prise de parole préparée : se présenter, introduire le sujet, le présenter, conclure.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-143-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-143'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- en tenant compte de l’intention et du destinataire (diversité des interlocuteurs) ; - en adaptant le volume, le débit, la posture, les expressions et le regard ; - en utilisant des règles de courtoisie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
