insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-18-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-18'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Connaitre des expressions pour demander la parole, pour introduire une prise de parole spontanée et pour la structurer.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
