insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-94-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-94'), 'primaire', array['P5']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - les connaissances personnelles mobilisées ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (texte-illustrations éventuelles, liens logiques, chronologiques, organisateurs textuels, reprise de l’information*) ; - les informations essentielles, le sens global du message ; - le sens du message grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
