insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-53-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-53'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Regarder son destinataire, l’auditoire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-53-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-53'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Utiliser à bon escient des expressions types pour respecter des règles de courtoisie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-53-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-53'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Tenir compte des réactions de son auditoire/ses interlocuteurs et y adapter son message : - vigilance à l’effet produit par les idées émises ; - ajout d’éléments ou de précisions en fonction des réactions ; - ajustement des propos selon le destinataire ; - reformulation en fonction des réactions obtenues.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-54-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-54'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Témoigner de son écoute en : - regardant l’énonciateur ; - adoptant une posture d’écoute ; - signalant celle-ci par des gestes (mimiques, sourire, signe de tête) ; - formulant un commentaire sur la voix (volume, débit, intonation) ; - reformulant ce qui a été dit.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
