insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-78-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-78'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Prendre la parole pour produire/élaborer un message qui combine certains des éléments suivants en s’appuyant ou non sur un support de présentation :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-144-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-144'), 'primaire', array['P6']::text[], 'Français', 'attendu', '- en restant dans le sujet ; - en tenant compte de l’intention, du destinataire (diversité, réactions des interlocuteurs), des freins et des facilitateurs de la communication ; - en l’organisant selon une structure textuelle adéquate ; - en utilisant les connecteurs* ; - en utilisant le lexique courant ou spécifique à une thématique ou un champ disciplinaire adéquat ; - en utilisant les formes verbales qui assurent la cohérence temporelle* et en utilisant les structures de phrase correctes ; - en assurant la reprise d’information (substituts lexicaux et grammaticaux, pronoms personnels).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-144-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-144'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Interagir avec autrui', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-82-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-82'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Prendre la parole dans un groupe : - en osant s’exprimer ; - en intervenant au moment approprié ; - en questionnant ses interlocuteurs ; - en répondant à des questions ; - en dégageant des liens entre les propos échangés et en regroupant ce qui a été dit ; - en respectant les règles de courtoisie.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-82-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-82'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Partager ses écrits réflexifs : - en cherchant à préciser sa pensée ; - en explicitant ses idées, apportant des exemples, évoquant des faits ; - en confrontant des idées entre elles.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
