insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-4-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-4'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Textes contenant Textes contenant Textes contenant Textes contenant 50 % de formes 60 % de formes 80 % de formes 90 % de formes correctes correctes correctes correctes', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-4-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-4'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Figure 2 : Progression des apprentissages en écriture', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-6-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-6'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Caractériser : - les paramètres de la communication : énonciateur, destinataire, message, contexte (temps et lieu) ; - les intentions de communication : informer, enjoindre, convaincre, procurer de l’agrément, donner à réfléchir.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-164-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-164'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Identifier le niveau de langue adapté à la situation de communication.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-165-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-165'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Identifier les règles de courtoisie : temps et tours de parole, critères de présentation orale et écrite, respect du point de vue d’autrui…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-166-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-166'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Reconnaitre les structures de textes : narratif, argumentatif, explicatif, descriptif, dialogué.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-167-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-167'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Identifier les types de support utilisé, y compris numérique.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-167-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-167'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Reconnaitre les éléments du paratexte : couverture, titre, sous-titre, chapeau, intertitre, support de publication, bibliographie de l’auteur, image, hyperlien, bruitage, générique…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-168-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-168'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Expliciter les stratégies d’écoute et de lecture : - attitude de concentration ; - attitude corporelle adéquate ; - choix d’une posture et d’une modalité d’écoute ou de lecture.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-168-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-168'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Distinguer les postures de lecture : - fonctionnelle (centrée sur l’information) vs littéraire (centrée sur la richesse du texte) ; - participative (centrée sur les émotions) vs distanciée* (analytique) ; - compréhensive (centrée sur les droits du texte) vs interprétative (centrée sur les droits du lecteur).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-168-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-168'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Distinguer les modalités de lecture : - intégrale/sélective ; - détaillée/globale (ou « de survol »).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-168-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-168'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Distinguer les modalités d’écoute : - directe/différée ; - intégrale/sélective ; - avec ou sans retour en arrière ; - avec ou sans traces.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-169-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Citer les trois étapes constitutives de la production orale ou écrite (planification, textualisation/mise en voix, révision/correction).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-169-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Expliciter la planification : analyse de la situation de communication, recherche d’idées, élaboration d’un plan, gestion du temps, choix d’une démarche...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-170-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-170'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Reconnaitre les caractéristiques des genres littéraires et non littéraires traités (voir Tableau des genres proposés en page 32).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
