insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-172-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-172'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Repérer thèse, arguments, exemples.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-173-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-173'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Identifier le rôle des paramètres de la voix en fonction de la situation de communication : - débit ; - intonation ; - volume ; - articulation ; - pauses ; - accents d’insistance ; - prononciation...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-174-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-174'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Identifier le rôle des paramètres du corps en fonction de la situation de communication : - posture ; - gestuelle ; - regard ; - mimiques ; - déplacements.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-169-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Citer les trois étapes constitutives de la production orale ou écrite (planification, textualisation/mise en voix, révision/correction).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
