insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-178-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-178'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Connaitre : - le système des modes et des temps du présent ; - les systèmes des temps du passé ; - l’emploi des modes et des temps pour exprimer une injonction (futur, impératif, infinitif).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
