insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-193-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-193'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Faire apparaitre l’organisation du texte (paragraphes, titres, intertitres, organisateurs textuels, hyperliens…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-193-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-193'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Dégager les connexions (mots ou expressions qui assurent l’enchainement des informations, des phrases et des paragraphes de manière chronologique, logique).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-193-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-193'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Expliciter les liens anaphoriques (synonymes, pronoms, paraphrases…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-194-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-194'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser : - des liens logiques/sémantiques entre les informations ; - des organisateurs textuels et/ou marques visibles de l’organisation ; - les marques de ponctuation ; - des anaphores adéquates ; - le système de temps adéquat (concordance des modes et des temps).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-195-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-195'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser : - le vocabulaire adéquat adapté au récepteur ou à l’auditoire, à la situation/à la thématique et au genre ; - les termes mélioratifs/péjoratifs.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-196-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-196'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Expliciter le sens d’un mot : - dans son contexte ou en se référant à son cotexte*, à sa famille, à son étymologie, à sa forme… - en consultant un ouvrage de référence, un référentiel, y compris numérique.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-196-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-196'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Traiter/utiliser les unités grammaticales', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-197-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-197'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser/prendre en compte une syntaxe adéquate à la prestation : - répétition ; - élision ; - liaisons obligatoires ; - connexions ; - système de temps...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-198-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-198'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Traiter dans le texte les indices grammaticaux qui contribuent à produire le sens : marques nominales et verbales (terminaisons) ; - marques de types et de formes de phrases ; - indices spatiotemporels ; - liens logiques et sémantiques entre les informations essentielles ; - référent des principales anaphores…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-198-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-198'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser des indices grammaticaux qui contribuent à produire le sens : - des expansions du nom ; - des indices temporels (temps verbaux, adverbes…) ; - conjuguer correctement les verbes aux modes (indicatif et impératif) et temps adéquats.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-199-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-199'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Reconnaitre les constituants d’une phrase* : - complexe : la proposition principale et la proposition subordonnée circonstancielle de comparaison, de cause et de conséquence, de temps. - multiple : deux phrases simples coordonnées ou juxtaposées.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
