insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-173-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-173'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Caractériser le rôle des paramètres de la voix en fonction de la situation de communication : - débit ; - intonation ; - volume ; - articulation ; - pauses ; - accents d’insistance ; - prononciation ;', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-174-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-174'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Caractériser le rôle des paramètres du corps en fonction de la situation de communication : - posture ; - gestuelle ; - regard ; - mimiques ; - déplacements.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-169-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Citer les trois étapes constitutives de la production orale ou écrite (planification, textualisation/mise en voix, révision/correction).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-169-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Expliciter la textualisation/mise en voix : sélection des idées, construction du texte, progression thématique, structure...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-175-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Déterminer les anaphores : pronom, synonyme, répétition.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-175-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Énoncer : - les relations sémantiques exprimées par certains connecteurs*/liens sémantiques : manière, comparaison, cause-conséquence, but, opposition, temps, hiérarchie ; - l’emploi des marques de ponctuation les plus courantes liées aux productions ; - l’organisation du texte, le fonctionnement du découpage en paragraphes.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-175-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Différencier quelques figures de style majeures : la comparaison, l’antithèse, l’anaphore, la personnification, l’ellipse.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-175-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Citer les organisateurs textuels/marques visibles d’organisation du texte (titraille, puces, police…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-175-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Reconnaitre des indices grammaticaux qui contribuent à produire le sens : - les connecteurs*/liens sémantiques (chronologie, hiérarchie, espace) ; - les anaphores (pronom, synonyme, répétition).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-176-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-176'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Reconnaitre : - les termes spécifiques d’une thématique ou d’un objet ; - les termes mélioratifs/péjoratifs ; - le sens propre, le sens figuré ; - des expressions idiomatiques ou figées ; - les sens multiples d’un mot (polysémie) ; - les préfixes et leur impact sur le sens du mot : in-, ex-, pré-, post-, co-, inter-, hyper-, super-, sub-/sous-, anti-, pro-, auto-, homo-, hétéro-...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-177-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-177'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Reconnaitre : - la répétition ; - l’usage de l’élision ; - l’usage des liaisons obligatoires/interdites ; - des connexions ; - le système de temps.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-178-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-178'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Caractériser dans le texte les indices grammaticaux qui contribuent à produire le sens : - les marques nominales et verbales (terminaisons) ; - les marques de types et de formes de phrases ; - les indices spatiotemporels.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
