insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-197-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-197'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Utiliser/prendre en compte une syntaxe adéquate à la prestation : - répétition ; - élision ; - liaisons obligatoires ; - connexions ; - système de temps...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-198-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-198'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Traiter dans le texte les indices grammaticaux qui contribuent à produire le sens : - marques nominales et verbales (terminaisons) ; - marques de types et de formes de phrases ; - indices spatiotemporels et modaux ; - les expansions du nom.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
