insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-199-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-199'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Reconnaitre les constituants d’une phrase* : - complexe : • la proposition principale et les propositions subordonnées complétive et circonstancielle de comparaison, de cause et de conséquence, de but, d’opposition, de temps ; • la proposition subordonnée relative (pronom sujet et complément direct). - multiple : deux phrases simples coordonnées ou juxtaposées.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
