insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-168-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-168'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Distinguer les modalités d’écoute : - directe/différée ; - intégrale/sélective ; - avec ou sans retour en arrière ; - avec ou sans traces.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-169-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Citer les trois étapes constitutives de la production orale ou écrite (planification, textualisation/mise en voix, révision/correction).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-169-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-169'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Expliciter la planification : analyse de la situation de communication, recherche d’idées, élaboration d’un plan, gestion du temps, choix d’une démarche...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
