insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-175-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Déterminer les anaphores : pronom, synonyme, répétition.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-175-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Distinguer : - les relations sémantiques et marqueurs de temps, de manière, de but, de comparaison (similitude-différence-opposition) de condition, de cause et de conséquence, concession, hypothèse ; - l’emploi des marques de ponctuation les plus courantes liées aux productions ; - l’organisation du texte, le fonctionnement du découpage en paragraphes.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-175-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Différencier quelques figures de style majeures : la comparaison, l’antithèse, l’ellipse, l’anaphore, la métaphore, la personnification.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-175-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-175'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Citer les organisateurs textuels/marques visibles d’organisation du texte (titraille, puces, police…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-176-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-176'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Reconnaitre : - les termes spécifiques d’une thématique ou d’un objet ; - les termes mélioratifs/péjoratifs ; - le sens propre, le sens figuré ; - des expressions idiomatiques ou figées ; - les sens multiples d’un mot (polysémie) ; - les préfixes et leur impact sur le sens du mot ; - les moyens lexicaux de concision.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
