insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-178-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-178'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Caractériser dans le texte les indices grammaticaux qui contribuent à produire le sens : - les marques d’enchainement question/réponse ; - les marques nominales et verbales (terminaisons) ; - les marques de types et de formes de phrases ; - les indices spatiotemporels.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
