insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-222-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-222'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Se construire une identité de lecteur. Les élèves sont invités, via ce savoir-faire, à prendre appui sur leurs connaissances culturelles (littéraires, scientifiques, artistiques…) pour justifier leurs préférences (autrices et auteurs, genres…). Ils apprennent aussi à se donner des défis (variétés des textes, longueur, stratégies à expérimenter…). (SF, P1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-222-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-222'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Se situer personnellement par rapport au document : - selon le genre et le support, expliquer et justifier les effets de sens produits par les choix (techniques, stylistiques, narratifs, iconographiques…) d’un auteur ; - partager une impression, une émotion, une perception et l’étayer ; - formuler une appréciation fondée sur des critères pertinents ; - établir des liens avec le monde. (SF, S1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-223-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-223'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Se construire une culture littéraire : - connaitre des œuvres du patrimoine littéraire rencontrées à l’école ;', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-224-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-224'), 'primaire', array['S3']::text[], 'Français', 'attendu', '- connaitre des œuvres contemporaines marquantes pour la jeunesse rencontrées à l’école. (S, P1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-225-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-225'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Prendre la parole dans un groupe : - en osant s’exprimer ; - en intervenant au moment approprié ; - en questionnant ses interlocuteurs ;', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-226-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-226'), 'primaire', array['S3']::text[], 'Français', 'attendu', '- en répondant à des questions ; - en dégageant des liens entre les propos échangés et en regroupant ce qui a été dit ; - en respectant les règles de courtoisie. (C, P1 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-227-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-227'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Produire un texte ou un discours à structure argumentative ; prendre position et étayer son opinion (relative à un fait d’actualité, à un choix, à une expérience…). (C, S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-228-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-228'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maîtriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-229-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-229'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Observer des régularités : - récolter des éléments en fonction de leurs similitudes pour constituer des groupes ; - étiqueter les groupes (ex. : classe, fonction) et les sous-groupes (ex. : nom, déterminant...). (SF, P3 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Observer que les mots qui appartiennent à une même famille morphologique ont un lien de sens. Observer que les mots qui ont un lien de sens ne sont pas toujours de la même famille morphologique. (SF, P1-P2)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Repérer des différences et des similitudes morphologiques et de relations sémantiques (synonymes, parties d’un tout, ordre d’intensité) entre des mots écrits.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Observer la construction des mots formés par composition et par dérivation.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Justifier une particularité orthographique en s’appuyant sur le préfixe ou le suffixe.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Classer les mots selon leur intensité. (SF, P4 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Utiliser, en tenant compte de la situation de communication, les mots du lexique spécifique à une thématique ou un champ disciplinaire. Réinvestir de nouveaux mots et de nouvelles expressions ayant émergé en classe, issus d’œuvres de littérature de jeunesse et provenant d’autres disciplines scolaires. Utiliser des mots ou expressions qui modulent l’intensité des noms et verbes.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Utiliser des mots et expressions qui marquent la négation, la certitude, la probabilité des informations envisagées.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Remplacer un mot par un mot du même champ lexical.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Remplacer un mot par un autre de même sens ou de sens contraire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Remplacer un mot générique par un spécifique ou l’inverse. (SF, P1 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Distinguer les relations sémantiques et marqueurs de temps, de manière, de but, de comparaison (similitude-différence-opposition), de condition, de cause et de conséquence, de concession, d’hypothèse. (S, S1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-231-7', (select id from public.curriculum_item where version = '2022' and code = 'FR-231'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Décrire la chronologie d’un texte simple et structuré. (SF, P1 à P6) Expliquer les liens logiques existant entre les idées du texte. (SF, P1 à P6) Dégager la chronologie : la rétrospection, anticipation, ellipse… (S, S1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-232-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-232'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Intégrer de nouvelles informations à son réseau de connaissances et les verbaliser. Recourir à des sources documentaires pertinentes. Choisir un moyen de consigner des traces de ses apprentissages (schéma, notes, tableau, carnet de terrain). Recourir à une diversité de sources. Recourir à des techniques et des outils de consultation (mots clés, moteur de recherche, index…). (SF, P1 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Réviser sa production écrite Relire sa production et vérifier : - le contenu des idées ; - leur organisation dans des phrases respectant une structure dominante choisie (à l’aide d’une grille de révision) ; - le respect de l’intention poursuivie ; - la précision du vocabulaire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Définir des pistes de révision.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Ajuster sa production en fonction des pistes de révision. (SF, P1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Évaluer sa prise de parole préparée Vérifier, selon la réaction du ou des récepteurs, si l’intention de communication a été atteinte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Ajuster son propos quand on perd l’attention de son interlocuteur.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-233-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-233'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Relever des éléments moins réussis de sa communication : - en cernant ce qui n’a pas été bien saisi ; - en reformulant les propos énoncés (précisions, ajouts...) ; - en commentant les blocages survenus ; - en réfléchissant à des facilitateurs de communication. (SF, P1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-234-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-234'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Expliquer une stratégie de lecture et d’écriture Présenter sa stratégie de lecture (linéaire, tabulaire, hypertextuelle - avec ou sans annotation - globale ou sélective - survol/repérage/approfondissement…) adaptée au projet, au support et au temps accordé. Justifier des structures et/ou schémas (argumentatif, descriptif, narratif) en fonction de la production. Évaluer et adapter sa stratégie le cas échéant. (SF, P1 à S3) Réfléchir à sa pratique de lecteur : - expliquer les stratégies de compréhension et d’interprétation mises en œuvre ; - autoévaluer sa maitrise des stratégies ; - évaluer le rôle joué par les stratégies dans la compréhension ou l’interprétation d’un texte ; - verbaliser les connaissances acquises sur la langue, sur les genres et structures de textes et sur la culture. (SF, P4 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-235-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-235'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Tenir compte des paramètres de la situation de communication Identifier l’énonciateur, le destinataire, l’intention dominante, le message et le contexte pour planifier sa prise de parole, son écoute, sa lecture et son écrit. Adapter/tenir compte du niveau de langue (familier, courant, soutenu). S’adapter à la diversité des interlocuteurs : - connu/inconnu ; - familier/non familier ; - un/plusieurs ; - du même âge/plus jeune/plus âgé ; - d’ici/d’ailleurs. (S-SF, P5-P6) Pratiquer une lecture distanciée (droits du lecteur) Dégager les valeurs défendues, le message véhiculé dans un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Identifier le narrateur.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Associer des valeurs et des intentions à un personnage.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'S’interroger sur l’intention de l’auteur.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Déterminer si le point de vue de l’auteur est objectif ou subjectif.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Distinguer les faits et les opinions.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-7', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Déterminer comment la forme du texte (champs lexicaux, utilisation des adjectifs et des adverbes…) et les procédés utilisés par les autrices et auteurs contribuent au sens du texte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-8', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Comparer la vision du monde proposée dans un texte à sa vision personnelle. (SF, P2 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-9', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Appréhender le réel et l’imaginaire, le factuel et le fictionnel. (SF, P1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-10', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Dégager et reformuler : - les éléments vraisemblables ; - les éléments invraisemblables. (SF, P3 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-11', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Identifier les effets de sens produits par le travail de l’auteur : - gestion de la temporalité (linéarité, anticipation, retours en arrière…) ; - récits parallèles, enchâssés ; - rythme de la narration (ellipse, résumé…), du montage ; - focalisation interne/externe ; - narration unique/polyphonique ; - présence d’inventions langagières (figures de style…), ton utilisé (sérieux, comique, ironique…) ; - mise en page ; - représentation figurative ou non figurative (choix de couleurs, floutage, cadrage, incrustation…). (S, S1 à S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-12', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Partager ses écrits réflexifs : - chercher à préciser sa pensée ; - expliciter ses idées, apporter des exemples, évoquer des faits. (SF-C, P3 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-236-13', (select id from public.curriculum_item where version = '2022' and code = 'FR-236'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Confronter des idées entre elles (SF-C, P5-P6).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-237-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-237'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-4', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Réaliser une planification : analyser la situation de communication, rechercher des idées, élaborer un plan, gérer le temps, choisir une démarche. (SF, S1 à S3) Expliciter la textualisation/mise en voix : sélection des idées, construction du texte, progression thématique, structure... (S, S1 à S3) Écrire pour informer, donner du plaisir/susciter des émotions, persuader, enjoindre Rédiger un écrit qui combine certains des éléments suivants en mobilisant des ressources (référentiels) : - en restant dans le sujet ; - en tenant compte de l’intention et du destinataire ; - en l’organisant selon une structure textuelle simple donnée ; - en utilisant les traits de ponctuation adéquats ; - en orthographiant correctement les mots connus et inconnus et en appliquant les règles d’orthographes grammaticale et lexicale ; - en utilisant les connecteurs ; - en utilisant les modes et les temps appropriés pour assurer la cohérence temporelle ; - en utilisant les substituts lexicaux et grammaticaux ; - en recourant aux lexiques courant et spécifique à une thématique ou un champ disciplinaire ; - en utilisant l’outil numérique pour présenter sa production. (C, P1 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Résumer un court texte narratif.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
