insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-342-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-342'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Traduire un extrait de texte latin non vu, en français correct, tout en tenant compte des éléments textuels et contextuels31.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-326-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-326'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exprimer la signification d’un extrait de texte sous des formes variées (production écrite, artistique ou orale).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-326-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-326'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Au travers d’une production créative personnelle, écrite ou orale, mettre en évidence un aspect significatif du monde gréco-romain et ses prolongements ou ses ruptures.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-220-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-220'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Se connaitre et s’ouvrir aux autres requièrent de développer une conscience de soi et de l’autre, du temps et de l’espace ainsi que du collectif.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-7', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-223-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-223'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Éléments culturels de la civilisation gréco-romaine : - cadre géographique et historique de la civilisation gréco-romaine ;', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-224-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-224'), 'primaire', array['S3']::text[], 'Français', 'attendu', '- emprunts actuels au latin et au grec ; - vie quotidienne : organisation sociale. (S, S2 et S3) Manifester sa compréhension d’un aspect significatif du monde romain : au travers d’une production créative personnelle, écrite ou orale, mettre en évidence un aspect significatif du monde antique et ses prolongements ou ses ruptures. (C, S2 et S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-228-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-228'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maîtriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-8', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-229-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-229'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'L’organisation syntaxique propre aux langues anciennes et leur caractère flexionnel amènent l’élève à observer, comparer, raisonner, catégoriser et ordonner des éléments linguistiques. Les savoir-faire ainsi développés sont', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Par ailleurs, la pratique de la justification des choix d’analyse, rendus nécessaires par la polysémie de certaines désinences, entraine l’élève à prendre conscience de ses apprentissages.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-230-7', (select id from public.curriculum_item where version = '2022' and code = 'FR-230'), 'primaire', array['S3']::text[], 'Français', 'attendu', '- Classer des éléments. - Comprendre un système linguistique. - Comprendre des significations. - Élaborer des significations. - Établir un lien avec des éléments de référence. - Utiliser des références. - Analyser des informations. (SF, S2 et S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-235-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-235'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-9', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-343-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-343'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Les savoirs et savoir-faire cités ci-dessous contribuent au développement des capacités de formulation d’hypothèses, d’analyse, de synthèse et de critique, à partir de différents supports reconnus dans leurs caractéristiques propres. Caractéristiques de différents supports ou documents iconographiques ou architecturaux (peinture, sculpture, céramique, édifice, mosaïque, pièce de monnaie…). (S, S2 et S3) Divinités et leurs attributs caractéristiques. (S, S2) Figures héroïques, mythiques et légendaires. (S, S3) Analyser des informations et notamment relier : - un extrait à son contexte géographique et historique ; - un extrait à un auteur, à un genre littéraire, à un archétype ; - un extrait à des connaissances culturelles et à des documents de natures variées. (SF, S2 et S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-237-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-237'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-10', (select id from public.curriculum_item where version = '2022' and code = 'FR-221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-15', (select id from public.curriculum_item where version = '2022' and code = 'FR-238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'La créativité des élèves est spécifiquement sollicitée dans les différentes formes de productions attendues pour réexprimer la signification des textes découverts en classe et par les savoir, savoir-faire et compétence suivants : - figures héroïques, mythiques et légendaires : dégager le sens d’un mythe ; (S, S3) - élaborer des significations ; (SF, S3) - manifester sa compréhension d’un extrait de texte latin mis en contexte : exprimer le sens d’un extrait de texte sous des formes variées (production écrite, artistique ou orale). (C, S3)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-240-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-240'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'tière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-245-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-245'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-246-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-246'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
