insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-11-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-11'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Production orale très courte et simple : • pour informer ; • constituée de mots isolés, de mots internationalement partagés et d’expressions toutes faites.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
