insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-12-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-12'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', '• pour informer ; • constituée de mots isolés, de mots internationalement partagés et d’expressions toutes faites.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-12-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-12'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions ; - de formules de politesse et de salutations. • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-12-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-12'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui respecte l’interlocuteur.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-24-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-24'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de quelques informations pertinentes par rapport à la tâche, au travers, par exemple, d’un dessin, un schéma, une liste, un mime, un ou plusieurs mots.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-14-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-14'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de quelques informations pertinentes par rapport à l’action à poser.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-14-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-14'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Action en exécution d’une consigne au travers, par exemple d’un mouvement, d’une manipulation d’objet, d’un geste, d’un déplacement qui témoigne de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-15-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-15'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Repérage d’un ou de quelques éléments qui témoignent, par exemple, du patrimoine, de traditions, de la création artistique ou de modes de vie.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P4-25-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-25'), 'primaire', array['P4']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de la compréhension à travers l’identification de quelques informations pertinentes par rapport à la tâche, au travers, par exemple, d’un dessin, un schéma, une liste, un mime, un ou plusieurs mots.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
