insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P6-63-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-63'), 'primaire', array['P6']::text[], 'Langue moderne', 'attendu', 'Production écrite très courte : • constituée de mots isolés, énoncés très courts juxtaposés (généralement constitués d’expressions idiomatiques) et/ou de phrases très simples adaptées de modèles ; • pour nommer des personnes, des lieux, des animaux ou des objets figurant sur des illustrations ou des schémas personnels ou non, à l’aide de divers outils (ex. : un manuel scolaire, un cahier d’exercices, une application numérique, un imagier, un référentiel de classe, un jeu) ; • pour donner des instructions très brèves.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P6-63-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-63'), 'primaire', array['P6']::text[], 'Langue moderne', 'attendu', 'Cette production écrite : • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P6-63-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-63'), 'primaire', array['P6']::text[], 'Langue moderne', 'attendu', 'Adaptation de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui respecte l’interlocuteur.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
