insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-59-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Production orale courte et simple : • pour informer et/ou pour faire agir ; • constituée essentiellement de phrases courtes, simples, juxtaposées ou éventuellement articulées.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-59-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • respecte les caractéristiques définies dans l’annexe 3 en utilisant, au besoin, les stratégies adéquates.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-59-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-60-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-60'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Production orale courte et simple : • pour s’informer et informer autrui et/ou pour faire agir ; • constituée essentiellement de phrases courtes, simples, juxtaposées ou éventuellement articulées.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-60-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-60'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions ; - de questions ; - d’injonctions ; - de formules de politesse et de salutations. • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-60-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-60'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S1-92-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-92'), 'primaire', array['S1']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de la plupart des informations pertinentes par rapport à la tâche, au travers, par exemple, d’un dessin, un schéma, une liste, un mime, de phrases simples.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
