insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-59-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Production orale courte et simple : • pour informer et/ou pour faire agir ; • constituée essentiellement des deux types de phrases suivants : - courtes, simples et juxtaposées ; - courtes, simples et articulées.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-59-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • respecte les caractéristiques de l’annexe 7 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-59-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-59'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-176-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-176'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Production orale courte et simple • pour s’informer et informer autrui et/ou pour faire agir ; • constituée essentiellement des deux types de phrases suivants : - courtes, simples et juxtaposées ; - courtes, simples et articulées.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-176-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-176'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions ; - de questions ; - d’injonctions ; - de formules de politesse et de salutations. • respecte les caractéristiques de l’annexe 7 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-176-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-176'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-177-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-177'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de la plupart des informations pertinentes par rapport à la tâche, au travers, par exemple, d’un dessin, un schéma, une liste, un mime, de phrases simples.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-93-4', (select id from public.curriculum_item where version = '2022' and code = 'LM-93'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification d’informations pertinentes par rapport à l’action à poser.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-93-5', (select id from public.curriculum_item where version = '2022' and code = 'LM-93'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Action en exécution d’une suite de consignes ou d’instructions au travers, par exemple, de mouvements, de manipulations d’objets, de gestes, de déplacements qui témoignent de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-93-6', (select id from public.curriculum_item where version = '2022' and code = 'LM-93'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Transmission, dans la langue de scolarisation, à une tierce personne, des éléments essentiels et pertinents contenus dans des instructions ou informations reçues en langue cible.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-93-7', (select id from public.curriculum_item where version = '2022' and code = 'LM-93'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Identification d’un ou plusieurs éléments qui témoignent :', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-15-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-15'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', '• par exemple, du patrimoine, de traditions, de la création artistique, de modes de vie ou de modes de pensées et façons de voir le monde ; • de similitudes et de différences dans les marqueurs sociolinguistiques ; • de similitudes et de différences entre cultures ou d’une conception stéréotypée des autres cultures.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
