insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-163-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-163'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Transmission, dans la langue de scolarisation, à une tierce personne, des éléments essentiels et pertinents contenus dans des instructions ou informations reçues en langue cible.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-18-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-18'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Identification d’un ou plusieurs éléments qui témoignent : • par exemple, du patrimoine, de traditions, de la création artistique, et notamment littéraire, de modes de vie ou de modes de pensées et façons de voir le monde ; • de similitudes et de différences dans les marqueurs sociolinguistiques ; • de similitudes et de différences entre cultures ou d’une conception stéréotypée des autres cultures.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
