insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-185-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-185'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Les productions attendues permettent à l’élève d’apprendre à : - coopérer ; - négocier en découvrant et en prenant en compte le point de vue d’autrui ;', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève prend conscience de la chronologie des évènements et trouve des moyens linguistiques pour les communiquer fidèlement.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'La connotation, inhérente aux différents temps dans la langue cible, donne à l’élève l’occasion de percevoir d’autres manières d’envisager le temps.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève communique à propos de son environnement et de la réalité qui l’entoure et prend conscience de l’existence de l’environnement dans lequel évolue l’autre.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-187-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-187'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'À travers les contenus d’apprentissage retenus, l’élève accède à différents vecteurs culturels propres à la langue apprise (livres, BD, chansons...).', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-187-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-187'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'À travers les contenus d’apprentissage retenus pour cette année, l’élève est', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-188-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-188'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'confronté à des données culturelles qui lui permettent d’identifier différents groupes d’appartenance ainsi que des éléments culturels qui les caractérisent. L’élève peut ainsi se situer comme membre d’un ou plusieurs groupes d’appartenance et accueillir', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-189-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-189'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'les autres groupes avec bienveillance et respect.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-189-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-189'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Apprendre à apprendre requiert que les élèves développent les opérations mentales de base susceptibles de les aider à organiser leurs apprentissages et la ré-', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-190-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-190'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maitriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-180-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-180'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-191-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-191'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève construit son apprentissage du lexique en catégorisant, ordonnant, observant et comparant les mots entre eux et avec la langue d’apprentissage. (S-SF/P3-P4)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-192-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-192'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève construit son apprentissage du lexique en catégorisant, ordonnant, observant et comparant les mots entre eux et avec la langue d’apprentissage. Il développe par ailleurs sa capacité à transférer (décontextualiser et recontextualiser).', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-193-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-193'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Parmi les outils numériques dont il dispose, l’élève est capable de choisir ceux qui sont adaptés à ses besoins et de les utiliser correctement.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-194-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-194'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Expérimenter le recours à différentes techniques et stratégies, évaluer leur efficacité et les combiner de façon adéquate pour résoudre des tâches productives et', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-195-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-195'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-180-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-180'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-196-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-196'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Identifier des informations pertinentes par rapport à la tâche.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-196-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-196'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’esprit d’entreprendre suppose de l’initiative, de la créativité, de l’innovation et de', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-197-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-197'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-180-4', (select id from public.curriculum_item where version = '2022' and code = 'LM-180'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Exemples de contenus ou d’attendus contributifs', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-198-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-198'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève adapte son comportement et/ou la formulation du message par le recours à des marqueurs sociolinguistiques en lien avec le contexte socioculturel, la structure ou l’intention communicative.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-199-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-199'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève développe sa créativité, sa confiance en lui, sa capacité à communiquer en utilisant les ressources linguistiques adéquates.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-200-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-200'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève pose progressivement des choix judicieux de manière autonome.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-201-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-201'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Oser prendre la parole pour se dire, demander, donner son avis et l’expliquer en tenant compte des interlocuteurs et du contexte.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-201-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-201'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Oser prendre des risques pour s’exprimer et communiquer son message même si cela entraine des erreurs.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-201-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-201'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en ma-', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-202-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-202'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'tière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-180-5', (select id from public.curriculum_item where version = '2022' and code = 'LM-180'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-203-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-203'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels. À travers les champs thématiques (ex. : caractérisation des personnes ; vie quotidienne ; transports, déplacements et voyages ; enseignement et apprentissage), la curiosité des élèves vis-à-vis de la diversité des métiers sera éveillée. D’une manière générale, la formation en langues modernes offrira la possibilité de sensibiliser à l’importance des langues étrangères en rapport au sein de mondes', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-204-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-204'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'socioprofessionnels divers.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-205-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-205'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève témoigne de sa prise de conscience de sa responsabilité locale sur l’environnement en évoquant quelques gestes écologiques de base, durables et équitables. (S-SF-C/LMI S3)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-205-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-205'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler, d’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-206-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-206'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-207-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-207'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, goûts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-180-6', (select id from public.curriculum_item where version = '2022' and code = 'LM-180'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-208-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-208'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Au travers du champ thématique n° 1 « Caractérisation des personnes » Description • traits de caractère • forces, faiblesses et aptitudes', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-208-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-208'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève prend conscience de sa personnalité, ses forces, ses faiblesses pour désigner des professions/métiers qui pourraient lui convenir. (S-SF-C/LMI S2 à S3)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-208-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-208'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Au travers du champ thématique n° 3 « Vie quotidienne » • activités routinières à l’école et à la maison L’élève - identifie des habitudes et des attitudes positives qui pourraient lui servir dans le monde du travail ; - prend conscience des similitudes et des différences entre la vie scolaire et le travail ; - prend connaissance de règlements (ex. : règlement de son école ou d’une école étrangère) et prend conscience de l’existence de règlements dans la vie professionnelle. (S-SF-C/S1 à S3)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-209-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-209'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Au travers du champ thématique n° 8 « Enseignement et apprentissage » • vie scolaire • cours suivis par l’élève • étapes du cursus scolaire • le système scolaire L’élève - reconnait les exigences des métiers et les associe à des matières scolaires ; - prend conscience du système scolaire afin de poser un choix pertinent pour la suite de ses études ; - prend conscience des différentes filières qui s’offrent à lui tant dans leurs possibilités que dans leurs restrictions.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-210-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-210'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Au travers de différents champs thématiques (ex. : sports et loisirs, achats et services), l’élève est amené à poser des choix voire à les concrétiser (ex. : organiser L’appropriation et la mise en œuvre des stratégies de communication relèvent également de cette éducation à des choix qui influencent la bonne concrétisation', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-211-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-211'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Au travers de champs thématiques associés à des apprentissages grammaticaux (expression du futur), l’élève est amené à parler de ses projets. (S-SF-C/LMI S2 à S3)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-212-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-212'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Les stratégies de communication qui visent à sensibiliser l’élève à la nécessité de vérifier et réviser ses hypothèses lui font prendre conscience que ses choix ne sont pas toujours définitifs et qu’il faut pouvoir se remettre en question.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-213-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-213'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Dans le cadre de la résolution de tâches (savoirs et compétences), l’élève est amené à poser des choix et à les justifier tant en production qu’en réception.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-213-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-213'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Même si l’argumentation en langue moderne n’est pas un attendu à ce stade, l’élève est cependant amené à expliquer ses choix dans le cadre de productions de type', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-214-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-214'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Stratégies de communication en lien avec l’expression orale sans interaction Voir Annexe 3 page 134 Stratégies de communication en lien avec l’expression orale en interaction Voir Annexe 3 page 141', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-215-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-215'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Stratégies de communication en lien avec l’expression orale sans interaction Voir Annexe 3 page 134', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-215-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-215'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'Stratégies de communication en lien avec l’expression orale en interaction Voir Annexe 3 page 141', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
