insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P2-3.1-8', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.1'), 'primaire', array['P2']::text[], 'Mathématiques', 'attendu', 'Utiliser, de manière adéquate, les termes liés à la cardinalité : - égal à, le même nombre que, autant que ; - moins que, plus petit que, autant en moins que ; - plus que, plus grand que, autant en plus que ; - vaut le double de, la moitié de…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
