insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-3.2-6', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Utiliser, en situations concrètes, le vocabulaire familier lié aux quatre opérations. Ex. : - Ajouter, augmenter de, avancer de, monter de, mettre en plus… - Regrouper, rassembler, mettre ensemble, mettre avec… - Reculer, enlever, retirer, cacher, perdre… - Chercher l’écart, la différence… - Faire des tas, des paquets, des piles de… - Prendre plusieurs fois… - Partager, répartir en… tas, distribuer à…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
