insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-20', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Utiliser, en fonction de l’opération et des nombres, la calculatrice pour effectuer des opérations.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-21', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Estimer l’ordre de grandeur du résultat d’une opération (addition, soustraction et multiplication), avant de calculer précisément.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-22', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Vérifier la plausibilité d’un résultat.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
