insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-24', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Utiliser les opérations réciproques (+, -) et (x, :) pour vérifier le résultat d’une opération.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-25', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Résoudre un problème faisant intervenir des opérations sur les nombres : - en traduisant une situation contextualisée par un dessin, une verbalisation puis l’écriture d’opérations mathématiques (+, -, x, :) ; - en estimant le résultat ; - en effectuant les calculs ; - en communiquant le résultat avec précision ; - en vérifiant la plausibilité de la réponse, et verbaliser sa démarche.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-3.2-26', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Rédiger un énoncé en partant : - de la communication du résultat ; Ex. : à la fin de la récré, Antoine a 28 cartes de collection. - d’un calcul et de son résultat ; Ex. : 5 x 12 euros = 60 euros.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Utiliser les mots : - trier : « a ou n’a pas…» (selon le critère défini) ; Ex. : la couleur. - classer (selon des caractéristiques définies au sein d’un critère) ; Ex. : rouge, jaune, bleu…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-2', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Reconnaitre une représentation de données en : - tableau ; - ensembles ; - arbre (dichotomique) ; - diagramme à bandes.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-3', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Formuler une question exigeant une réponse par oui ou par non.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-4', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Collecter des informations à partir d’une question permettant un classement des données récoltées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-5', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Organiser des objets représentés et des données : - par tri selon trois critères considérés successivement ; - par classement selon des caractéristiques déterminées au sein d’un critère.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-6', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Déterminer les critères appliqués dans l’organisation d’objets représentés.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-7', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Choisir, pour organiser des objets représentés : - un critère à appliquer à un tri ; - un critère et ses caractéristiques à appliquer à un classement.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-4.1-8', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Compléter le support donné en fonction de la situation pour représenter un tri ou un classement : - deux ensembles incluant une intersection ; - un arbre dichotomique (trois critères) ; - un tableau à double entrée ; - un diagramme à bandes horizontales ou verticales.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
