insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-S3-2.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.1'), 'primaire', array['S3']::text[], 'Mathématiques', 'attendu', 'À partir du graphique d’une fonction : - expliciter la démarche graphique permettant de déterminer une image ; - expliciter un critère visuel permettant de lire un zéro, l’ordonnée à l’origine, le minimum, le maximum ; - expliciter un critère visuel permettant de déterminer entre quelles valeurs la fonction est croissante ou décroissante ; - expliciter un critère visuel permettant de déterminer entre quelles valeurs la fonction est positive ou négative.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
