insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P2-50-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-50'), 'primaire', array['P2']::text[], 'Sciences', 'attendu', 'Décrire et expliquer le mode de reproduction et les étapes de la vie d’un animal. Expliquer à l’aide d’exemples que le vivant provient du vivant.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P2-51-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-51'), 'primaire', array['P2']::text[], 'Sciences', 'attendu', 'Décrire différentes situations météorologiques en lien avec les saisons, en utilisant des indicateurs variés (ex. : présence de soleil, de pluie, de neige, de grêle…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P2-51-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-51'), 'primaire', array['P2']::text[], 'Sciences', 'attendu', 'Identifier différentes ressources d’eau dans l’environnement (ex. : pluie, océan, lac, rivière…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P2-52-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-52'), 'primaire', array['P2']::text[], 'Sciences', 'attendu', 'Associer : - le thermomètre à la température ; - le pluviomètre à la quantité de pluie tombée ; - le moulin à vent, le drapeau, la girouette à la présence/ l’orientation du vent.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
