insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P3-95-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-95'), 'primaire', array['P3']::text[], 'Sciences', 'attendu', 'Identifier qu’un son est une vibration qui se propage dans une matière et qui peut être : - émise par une source de son ; - captée par un récepteur ; - perçue différemment en fonction de la distance par rapport à l’émetteur ; - renvoyée par des objets ; - arrêtée ou non par des matériaux.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
