insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-115-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-115'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Connaitre la signification de la « flèche » et du « maillon » dans une chaine alimentaire pour identifier que chaque vivant est mangé par celui qui suit.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-17-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Utiliser les termes suivants : « est mangé par », maillon, chaine alimentaire, proie, prédateur, carnivore, herbivore, omnivore.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-116-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-116'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Préciser le régime alimentaire d’un animal sur la base d’une source d’information.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-116-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-116'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Décrire des variations de l’alimentation de quelques', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-117-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-117'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'vivants, en fonction des saisons et de l’environnement.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-118-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-118'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Représenter, à l’aide de flèches, des relations alimentaires entre quelques vivants d’un même milieu de vie.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-119-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-119'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Établir des liens entre des adaptations d’animaux et leur chance de survie face à leurs prédateurs (ex. : mimétisme, camouflage, pelage d’hiver…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-119-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-119'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Établir des liens entre des adaptations d’animaux et leur chance de survie au cours des saisons (ex. : migration, pelage d’hiver, hibernation…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-119-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-119'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Visée 2 « Apprendre les sciences »', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-120-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-120'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Expliquer en quoi la disparition ou l’apparition d’un maillon peut modifier une chaine alimentaire.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-121-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-121'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Décrire le cycle naturel de l’eau en identifiant : - les changements d’état (évaporation, condensation, solidification, fusion) ; - les déplacements d’eau (précipitations, ruissèlement et infiltration) ; - les réserves d’eau (eaux de surface et eaux souterraines).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-122-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-122'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Identifier un gaz comme de la matière : il occupe tout l’espace disponible, peut exercer des forces et possède une masse.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-123-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-123'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Préciser que les changements d’état nécessitent un réchauffement ou un refroidissement. Identifier que la température de fusion/solidification de l’eau est de 0 °C. Identifier que la température d’ébullition de l’eau est de 100 °C.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-123-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-123'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Énoncer que les changements d’état sont réversibles, que la matière reste la même et que la masse reste constante.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-124-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-124'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Exprimer les mesures de masse dans les unités kg, g, et de température dans l’unité °C.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-17-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Utiliser les termes : température, cycle de l’eau, changement d’état, fusion, solidification, condensation, évaporation, ébullition, précipitations, ruissèlement, infiltration.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-125-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-125'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Montrer expérimentalement : - que la glace, la pluie et la vapeur d’eau sont toutes de la même matière : de l’eau.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-126-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-126'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', '- que l’eau occupe plus d’espace lorsqu’elle gèle, mais ne change pas de masse.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-126-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-126'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Montrer expérimentalement que la matière peut passer : - de l’état solide à l’état liquide lors d’une fusion ; - de l’état liquide à l’état gazeux lors d’une ébullition (au sein du liquide) ou d’une évaporation (en surface) ; - de l’état gazeux à l’état liquide lors d’une condensation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-126-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-126'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Choisir et utiliser correctement un instrument de mesure pour relever une température, pour mesurer une masse.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-127-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-127'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Réaliser une représentation légendée du cycle naturel de l’eau et préciser l’état de l’eau à chaque étape (ex. : le nuage est composé d’eau à l’état solide, liquide et gazeux ; dans l’air, il y a de l’eau sous forme de gaz, invisible…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-127-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-127'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Préciser des lieux de prélèvements possibles d’eau potable dans l’environnement.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-128-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-128'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Décrire un cycle naturel de l’eau, en mettant en évidence les transformations et la conservation de la matière dans un environnement donné.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-129-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-129'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Repérer quelques os sur un squelette : au minimum radius, cubitus (ulna), humérus, fémur, rotule (patella), péroné (fibula), tibia, vertèbres, crâne, côtes.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-129-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-129'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Repérer les articulations suivantes : hanche, genou,', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-129-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-129'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'cheville, épaule, coude, poignet.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-130-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-130'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Énoncer qu’un mouvement peut être commandé par le cerveau et que l’information circule par les nerfs. Préciser que pour qu’il y ait un mouvement d’un membre, il faut que le muscle soit au moins attaché à deux os par des tendons.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-130-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-130'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Identifier que lorsqu’il y a une mise en mouvement, un changement dans le mouvement ou un changement de la forme d’un objet, il y a une force qui s’exerce sur l’objet.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-131-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-131'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Énoncer les fonctions du squelette : soutien, locomotion et protection.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-17-4', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Utiliser les termes : muscles, tendons, os, articulations, hanche, genou, cheville, épaule, coude, poignet, squelette, radius, cubitus (ulna), humérus, fémur, rotule (patella), péroné (fibula), tibia, vertèbres, crâne, côtes, flexion, extension.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
