insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-13-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-13'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'S’exprimer de manière structurée en utilisant une terminologie appropriée à la situation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
