insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-136-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-136'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Décrire des changements physiques propres à la puberté (pilosité, mue de la voix, musculature, développement des seins, menstruations...).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-137-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-137'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Légender un schéma simplifié de l’appareil reproducteur de l’homme et de la femme (le pénis, les testicules, le vagin, la vulve, le clitoris, l’utérus, les ovaires).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-137-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-137'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Identifier la fonction des organes du système reproducteur de l’homme (au moins : pénis, testicules) et de la femme (au moins : ovaire, utérus, vagin).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-138-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-138'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Préciser le rôle respectif des deux sexes au cours de la reproduction sexuée (l’homme produit les spermatozoïdes et la femme les ovules).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-138-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-138'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Identifier la fécondation comme étant le résultat de la rencontre entre un spermatozoïde et un ovule.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-17-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Utiliser les termes suivants : puberté, pénis, testicule, ovaire, vagin, vulve, clitoris, utérus, fécondation, ovule, spermatozoïde.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
