insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-140-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-140'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Préciser que la pollinisation est le transport du pollen, des organes de reproduction mâles aux organes de reproduction femelles.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-140-4', (select id from public.curriculum_item where version = '2022' and code = 'SC-140'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Identifier la fécondation comme étant le résultat de la rencontre entre un grain de pollen et un ovule présent dans la plante.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
