insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-144-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-144'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'plantes afin d’identifier les organes en lien avec la reproduction.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-144-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-144'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Observer l’activité d’insectes pollinisateurs en lien avec une question.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-145-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-145'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Observer la transformation de fleurs en fruits contenant une/des graines et rassembler les informations pour les communiquer.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
