insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P5-147-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-147'), 'primaire', array['P5']::text[], 'Sciences', 'attendu', 'Mettre en évidence l’impact de la disparition d’insectes pollinisateurs sur les étapes de la vie d’une plante à fleurs, et plus largement sur l’environnement et/ou l’alimentation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
