insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-168-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-168'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'd’autres au niveau des poumons (dioxyde de carbone).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-17-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Utiliser les termes : nutriment, absorption intestinale, bouche, œsophage, estomac, intestin grêle, côlon, anus, glandes salivaires, pancréas, foie, veine, artère, ventilation, rythme cardiaque, trachée, bronche, poumon, alvéoles, dioxygène, dioxyde de carbone.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-169-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-169'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Évaluer le nombre de mouvements ventilatoires, avant et après l’effort, et les interpréter pour comprendre les liens entre ventilation et activité physique.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
