insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-247-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-247'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Décrire la structure interne de la Terre (noyau, manteau et écorce terrestre). Décrire comment le mouvement des plaques terrestres peut façonner le paysage et/ou entrainer des séismes.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-247-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-247'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Distinguer l’activité sismique de l’activité volcanique.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
