insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-248-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-248'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Préciser le rôle de Darwin dans l’élaboration de la théorie de l’évolution.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-249-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-249'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Préciser que les liens de parenté et les attributs partagés sont expliqués par l’évolution des vivants.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-249-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-249'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Décrire les éléments constitutifs d’un arbre phylogénétique : espèces actuelles, ancêtre commun et attributs partagés.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-250-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-250'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Énumérer les caractéristiques d’un ancêtre commun sur la base d’attributs partagés.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-251-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-251'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Citer des causes possibles retenues par les scientifiques pour expliquer une extinction massive d’espèces. Utiliser les termes : noyau terrestre, manteau terrestre, écorce terrestre, activité sismique, activité volcanique, sélection naturelle, arbre phylogénétique, espèce, ancêtre commun, extinction massive.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-252-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-252'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Analyser des informations historiques afin d’expliquer comment Darwin a proposé un modèle de sélection naturelle.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-252-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-252'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Repérer les différentes parties d’un arbre phylogénétique : espèces actuelles, ancêtres communs, attributs partagés.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-253-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-253'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Établir un lien entre la biodiversité du passé et la biodiversité actuelle (ex. : dinosaures et oiseaux).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-253-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-253'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Analyser des informations pour expliquer des causes et des conséquences d’une grande extinction d’espèces.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-254-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-254'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Transposer un ensemble emboité d’une collection d’animaux en un arbre phylogénétique simple.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-255-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-255'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Expliquer, à partir d’un arbre phylogénétique, que des animaux d’une collection donnée ont des liens de parenté et partagent des ancêtres communs.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-256-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-256'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Citer des activités humaines ayant un impact positif et des activités humaines ayant un impact négatif sur un écosystème (dont au moins, l’aménagement du territoire, la création de réserves naturelles, la pollution et l’exploitation excessive d’une ressource naturelle).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-17-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-17'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Utiliser les termes : pollution, réserve naturelle.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-257-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-257'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Consulter des documents pour : - présenter quelques impacts positifs et négatifs d’une activité humaine sur un écosystème ; - expliquer comment l’introduction ou la disparition d’une espèce à l’intérieur d’un écosystème peut l’influencer', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-258-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-258'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', '(ex. : disparition des abeilles, introduction d’une espèce invasive…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-258-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-258'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Visée 4 : « Orienter ses choix et agir en s’appuyant sur les sciences »', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-259-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-259'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Analyser une problématique en lien avec la biodiversité et envisager un plan d’action.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-260-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-260'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Préciser la proportion des principaux gaz dans l’air.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-221-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-221'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Identifier la molécule comme un assemblage d’atomes.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
