insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-281-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-281'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Identifier le corps qui exerce et le corps qui subit une force.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-281-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-281'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Identifier l’effet d’une force (déformation et/ou modification du mouvement).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-282-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-282'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Distinguer et illustrer des forces de contact et des forces à distance (ex. : frottements, magnétisme, électrostatique…).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-283-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-283'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Représenter une force par un modèle (flèche) : - dont son origine est un point situé sur l’objet qui subit la force ; - suivant sa droite d’action ; - dont son sens est déterminé ; ont sa longueur est proportionnelle à l’intensité (FA/B ) - d de la force.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-283-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-283'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Exprimer l’intensité (FA/B ) d’une force à son unité dans le Système International (SI), le newton et préciser que le nom de l’unité provient du nom du scientifique Isaac Newton.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-283-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-283'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Citer l’instrument de mesure de l’intensité d’une force.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-284-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-284'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Énoncer qu’une force exercée par un corps A sur un corps B est simultanée à une force exercée par le corps B sur ce corps A et toutes deux sont de même droite d’action, de même intensité, de sens opposé et de point d’application différent.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-285-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-285'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Identifier la masse d’un objet comme une grandeur physique liée à la quantité et à la nature de la matière qui constitue cet objet. Associer la masse (m) à son unité SI, le kilogramme (kg), et à son instrument de mesure.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-285-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-285'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Préciser que la masse d’un objet est invariable, quel que soit l’endroit où il se trouve.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
