insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-404-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-404'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Confronter les informations obtenues avec celles des autres à propos du son et de la lumière, pour réaliser une synthèse commune (SF, P3).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-404-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-404'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Recueillir, extraire et noter des informations en lien avec une question d’ordre scientifique, à partir de différents supports : l’utilisation de l’énergie en Belgique (SF, P6).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-404-4', (select id from public.curriculum_item where version = '2022' and code = 'SC-404'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Récolter des informations à propos de la présence de certains gaz et de particules fines dans certaines circonstances (ex. : l’air pollué, l’air inspiré et expiré, l’air « pur »…) (SF, S2).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-1-3', (select id from public.curriculum_item where version = '2022' and code = 'SC-1'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'L’esprit d’entreprendre suppose de l’initiative, de la créativité, de l’innovation et de', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-405-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-405'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
